<template>
  <AppShell><header class="page-head"><span class="eyebrow"><Route :size="15" />PROFILE-DRIVEN PATH</span><h1>{{ isOverview?'纵向学习路径':stageTitle }}</h1><p>{{ isOverview?'按周展开个性化计划，当前节点会自动定位。':'按顺序完成本周任务，资源结果会持续保存。' }}</p></header>
    <AsyncState :loading="loading" :error="error" :empty="!nodes.length" :empty-text="profile?'尚未生成学习路径':'请先完成学习画像'" @retry="load"><template #action><RouterLink v-if="!profile" class="primary-btn" to="/profile/collect">完成画像</RouterLink><button v-else class="primary-btn" :disabled="generating" @click="generatePath">生成学习路径</button></template>
      <div v-if="profile" class="path-profile"><span><UserRoundCheck :size="19" /></span><div><small>当前画像路径</small><strong>{{ profile.profileName || '学习画像' }} v{{ profile.version||1 }}</strong></div><RouterLink to="/profile">切换</RouterLink></div>
      <div class="metric-strip"><div><small>{{ isOverview?'计划周数':'任务数' }}</small><strong>{{ nodes.length }}</strong></div><div><small>已完成</small><strong>{{ doneCount }}</strong></div><div><small>整体进度</small><strong>{{ overallProgress }}%</strong></div></div>
      <div v-if="!isOverview" class="stage-actions"><RouterLink class="secondary-btn" to="/path"><ArrowLeft :size="16" />返回周次</RouterLink><button class="primary-btn" :disabled="preparing" @click="prepare"><LoaderCircle v-if="preparing" class="spin" :size="16" /><Layers3 v-else :size="16" />{{ preparing?'正在编排':'准备本周资源' }}</button></div>
      <VerticalPath v-model="expanded" :nodes="nodes" @open="openNode" />
    </AsyncState>

    <aside v-if="generating||trace.length||generationError" class="generation-drawer" :class="{expanded:traceOpen,failed:!!generationError}"><button type="button" @click="traceOpen=!traceOpen"><span v-if="generating" class="spinner"></span><CircleAlert v-else-if="generationError" :size="18" /><CheckCircle2 v-else :size="18" /><span><strong>{{ generationError?'路径生成失败':generating?'智能体正在编排路径':'路径已更新' }}</strong><small>{{ latestTrace.message||latestTrace.stage||'结构化校验已完成' }}</small></span><b>{{ generationProgress }}%</b></button><div class="progress-track"><i :style="{width:`${generationProgress}%`}"></i></div><div v-if="traceOpen" class="trace-list"><p v-if="generationError">{{ generationError }}</p><ol><li v-for="(event,i) in trace" :key="i"><b>{{ event.agentName||event.agent||'系统' }}</b><span>{{ event.message||event.stage }}</span></li></ol><button v-if="generationError" class="secondary-btn" @click="generatePath">重试</button></div></aside>
  </AppShell>
</template>
<script setup>
import { computed,onMounted,ref,watch } from 'vue';import { ArrowLeft,CheckCircle2,CircleAlert,Layers3,LoaderCircle,Route,UserRoundCheck } from 'lucide-vue-next';import { RouterLink,useRoute,useRouter } from 'vue-router';import AppShell from '../components/AppShell.vue';import AsyncState from '../components/AsyncState.vue';import VerticalPath from '../components/VerticalPath.vue';import { getPathConfig,getPathStage,getProfiles,getStageTasks,prepareStage,streamGeneratePath } from '../services/api.js';import { trackTask } from '../stores/tasks.js';import { activeProfile,pathWeeks,stageNodes,taskList } from '../utils/data.js'
const route=useRoute(),router=useRouter();const loading=ref(true),error=ref(''),profile=ref(null),nodes=ref([]),stageTitle=ref('本周任务'),expanded=ref(''),preparing=ref(false),generating=ref(false),trace=ref([]),traceOpen=ref(false),generationError=ref('')
const isOverview=computed(()=>!route.params.stageId);const doneCount=computed(()=>nodes.value.filter(n=>n.state==='done').length);const overallProgress=computed(()=>nodes.value.length?Math.round(doneCount.value/nodes.value.length*100):0);const latestTrace=computed(()=>trace.value.at(-1)||{});const generationProgress=computed(()=>Math.min(100,Math.max(0,Number(latestTrace.value.progress||latestTrace.value.payload?.progress||(generating.value?18:trace.value.length?100:0)))))
async function load(){loading.value=true;error.value='';expanded.value='';try{const p=await getProfiles();profile.value=activeProfile(p);if(!profile.value){nodes.value=[];return}if(isOverview.value){nodes.value=pathWeeks(await getPathConfig())}else{const body=await getPathStage(route.params.stageId);nodes.value=stageNodes(body);stageTitle.value=body?.stage?.title||body?.data?.stage?.title||'本周任务';const taskBody=await getStageTasks(route.params.stageId).catch(()=>({}));const listed=taskList(taskBody);awaitableTaskMap.value=Object.fromEntries(listed.map(t=>[t.taskId,t]));listed.filter(t=>['queued','running'].includes(t.status)).forEach(trackTask)}}catch(e){error.value=e.message}finally{loading.value=false}}
async function generatePath(){generating.value=true;generationError.value='';trace.value=[];traceOpen.value=true;try{await streamGeneratePath({persist:true,useLatestProfile:true,generationPhase:'first-week',weekStart:1,weekCount:1,totalWeeks:6,useLLM:true},({event,data})=>{if(event!=='heartbeat')trace.value.push({event,...(typeof data==='object'?data:{message:data})})});await load()}catch(e){generationError.value=e.message}finally{generating.value=false}}
async function prepare(){preparing.value=true;error.value='';try{const response=await prepareStage(route.params.stageId,{});taskList(response).forEach(trackTask);const latest=await getStageTasks(route.params.stageId);const listed=taskList(latest);awaitableTaskMap.value=Object.fromEntries(listed.map(t=>[t.taskId,t]));listed.forEach(trackTask)}catch(e){error.value=e.message}finally{preparing.value=false}}
function openNode(node){if(node.resourceType==='week'){router.push(`/path/${node.id}`);return}const match=Object.values((awaitableTaskMap.value)||{}).find(t=>t.cacheKey===node.cacheKey);if(match?.taskId)router.push(`/resources/task/${match.taskId}`);else prepare()}
const awaitableTaskMap=ref({})
watch(()=>route.params.stageId,load);onMounted(load)
</script>
<style scoped>.path-profile{display:grid;grid-template-columns:38px minmax(0,1fr) auto;align-items:center;gap:10px;margin-bottom:12px;padding:11px 13px;border:1px solid #d7e2dc;border-radius:7px;background:white}.path-profile>span{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#e8f3ed;color:#176f4b}.path-profile small,.path-profile strong{display:block}.path-profile small{color:#708078;font-size:9px}.path-profile strong{margin-top:3px;font-size:12px}.path-profile a{min-height:40px;display:flex;align-items:center;color:#176f4b;font-size:11px;font-weight:750}.metric-strip{margin-bottom:18px}.stage-actions{display:grid;grid-template-columns:1fr 1.45fr;gap:8px;margin-bottom:18px}.stage-actions>*{padding:0 9px;font-size:11px}.spin{animation:spin .8s linear infinite}.generation-drawer{position:fixed;right:14px;bottom:86px;left:14px;z-index:48;overflow:hidden;border:1px solid #bfd3c8;border-radius:7px;background:white;box-shadow:0 12px 32px rgba(28,49,39,.16)}.generation-drawer>button{width:100%;min-height:58px;display:grid;grid-template-columns:22px minmax(0,1fr) 34px;align-items:center;gap:9px;padding:9px 12px;border:0;background:#edf5f1;color:#176f4b;text-align:left}.generation-drawer>button span{min-width:0}.generation-drawer strong,.generation-drawer small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.generation-drawer strong{font-size:12px}.generation-drawer small{margin-top:3px;color:#6a7c72;font-size:9px}.generation-drawer>button>b{font-size:11px}.generation-drawer>.progress-track{border-radius:0}.trace-list{max-height:260px;padding:12px;overflow:auto}.trace-list>p{margin:0 0 10px;color:#a04435;font-size:11px}.trace-list ol{margin:0;padding:0;list-style:none}.trace-list li{display:grid;grid-template-columns:72px minmax(0,1fr);gap:8px;padding:7px 0;border-bottom:1px solid #e2e9e5;font-size:10px}.trace-list li b{color:#176f4b}.trace-list .secondary-btn{width:100%;margin-top:10px}</style>
